#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int minKBitFlips(int* nums, int numsSize, int k) {
    int active = 0, flips = 0;
    for (int i = 0; i < numsSize; ++i) {
        if (i >= k && nums[i-k] >= 2) active ^= 1;
        if (nums[i] == active) {
            if (i + k > numsSize) return -1;
            nums[i] += 2;
            active ^= 1;
            ++flips;
        }
    }
    return flips;
}

