class Solution {
    public int minKBitFlips(int[] nums, int k) {
        int n = nums.length, active = 0, flips = 0;
        for (int i = 0; i < n; i++) {
            if (i >= k && nums[i - k] >= 2) active ^= 1;
            if (nums[i] == active) {
                if (i + k > n) return -1;
                nums[i] += 2;
                active ^= 1;
                flips++;
            }
        }
        return flips;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().replaceAll("\\s", "");
        int close = s.indexOf("],");
        String arr = s.substring(2, close);
        String[] parts = arr.split(",");
        int[] nums = new int[parts.length];
        for (int i = 0; i < parts.length; i++) nums[i] = Integer.parseInt(parts[i]);
        int k = Integer.parseInt(s.substring(close + 2, s.length() - 1));
        System.out.println(new Solution().minKBitFlips(nums, k));
    }
}

